88	    /**
89	     * Add a new plant in a free neighbouring location if the two
90	     * following conditions are met:
91	     * 1- The production probability meets the random number
92	     * 2- There is a free adjacent location.
93	     *
94	     * @param newPlants (list<Species>)A list to return the new plant
95	     */
96	    protected void reproduce(List<Species> newPlants)
97	    {
98	        if (rand.nextDouble() <= getReproductionProbability())
99	        {
100	            Field field = getField();
101	            if (field != null)
102	            {
103	                List<Location> free = field.getFreeAdjacentLocations(getLocation());
104	
105	                if (free.size() > 0) {
