117	     * Its location in the field is cleared, but it still remembers its field and location
118	     */
119	    protected void setDead()
120	    {
121	        if(getLocation() != null) {
122	            deadDueTemperature = true;
123	            canRegrow = false; // set to false because if left as true, it could regrow the next step
124	            getField().clear(getLocation());
125	        }
126	    }
127	
128	    /**
129	     * The dead plant is placed back in the field if its previous location is empty and can regrow, otherwise do nothing.
130	     * If it grows, then it grows back to full health.
131	     */
132	    private void regrow()
133	    {
134	        if(getField().getObjectAt(getLocation()) == null && canRegrow)   {
135	            deadDueTemperature = false;
136	            getField().place(this, getLocation());
137	            currentHealth = maxHealth;
138	        }
139	    }
140	
141	    /**
142	     * Increase the plant's health by one if the random number meets the growing probability
143	     */
144	    private void grow()
145	    {
146	        if (currentHealth < maxHealth && rand.nextDouble() <= GROWING_PROBABILITY) {
147	            currentHealth++;
148	        }
149	    }
150	
151	    /**
152	     * The effect of getting eaten by an animal.
153	     * Decrement currentHealth by one, and set dead if the current health is less than 1.
154	     */
155	    public void isEaten()
156	    {
157	        currentHealth--;
158	
159	        if (currentHealth <= 0)    {
